import json, sys
from pathlib import Path

events_path = Path('.yoyo/state/events.jsonl')
if not events_path.exists():
    print('No events file found')
    sys.exit(1)

# Look for RunCompleted events with status 'cancelled' or terminal_reason indicating cancellation
with events_path.open() as f:
    for line in f:
        line = line.strip()
        if not line:
            continue
        try:
            evt = json.loads(line)
        except:
            continue
        kind = evt.get('event_type') or evt.get('kind', '')
        payload = evt.get('payload', {})
        if isinstance(payload, dict):
            data = payload.get('value', payload) if set(payload.keys()).issubset({'_yoyo', 'value'}) else payload
        else:
            data = {}

        if kind == 'RunCompleted':
            status = data.get('status', '')
            reason = data.get('terminal_reason', '')
            detail = data.get('error_detail', '')
            error = data.get('error', '')
            if status == 'cancelled' or reason == 'orphaned_previous_session' or 'cancelled' in str(reason).lower() or 'signal' in str(detail).lower():
                rid = evt.get('run_id') or (data.get('run_id', ''))
                print(f'RunCompleted: run_id={rid} status={status} terminal_reason={reason} error_detail={detail} error={error}')
" 2>&1 | head -30

