import json
from pathlib import Path

events_path = Path('.yoyo/state/events.jsonl')
if not events_path.exists():
    print('No events file found')
    import sys; sys.exit(1)

# Count RunCompleted events by status
statuses = {}
orphaned_count = 0
with events_path.open() as f:
    for line in f:
        line = line.strip()
        if not line:
            continue
        try:
            evt = json.loads(line)
        except:
            continue
        kind = evt.get('event_type') or evt.get('kind', '')
        if kind != 'RunCompleted':
            continue
        payload = evt.get('payload', {})
        if isinstance(payload, dict):
            data = payload.get('value', payload) if set(payload.keys()).issubset({'_yoyo', 'value'}) else payload
        else:
            data = {}
        status = data.get('status', '')
        reason = data.get('terminal_reason', '')
        detail = data.get('error_detail', '')
        is_orphan = reason == 'orphaned_previous_session'
        statuses[status] = statuses.get(status, 0) + 1
        if is_orphan:
            orphaned_count += 1
            rid = evt.get('run_id') or data.get('run_id', '')
            print(f'ORPHANED: run_id={rid} status={status} error_detail={detail}')

print(f'\\nStatus distribution: {statuses}')
print(f'Orphaned count: {orphaned_count}')
" 2>&1 | head -30

